/// <summary>
/// Load lại thông tin duyệt (biên tập viên + tổng biên tập)
/// </summary>
private void LoadReviewInfo(INFO_Information objInformation)
{
    if (objInformation == null)
    {
        objInformation = new INFO_Information();
        objInformation.InformationID = this.intInformationID;
        if (!objInformation.Get())
            return;
    }

    #region Load thông tin duyệt - Biên tập viên

    rdoIsReviewed1_null.Checked = rdoIsReviewed1_no.Checked = rdoIsReviewed1_yes.Checked = false;

    if (objInformation.IsReviewed1 == true)
        rdoIsReviewed1_yes.Checked = true;
    else if (objInformation.IsReviewed1 == false)
        rdoIsReviewed1_no.Checked = true;
    else
        rdoIsReviewed1_null.Checked = true;

    if (rdoIsReviewed1_null.Checked || objInformation.ReviewedDate1 == null)
        lblReview1_Info.Text = "";
    else
        lblReview1_Info.Text = "Biên tập viên: <b>" + objInformation.ReviewedUser1 + "</b> - Ngày giờ: <b>" + objInformation.ReviewedDate1 + "</b>";

    #endregion

    #region Load thông tin duyệt - Tổng biên tập

    rdoIsReviewed_null.Checked = rdoIsReviewed_no.Checked = rdoIsReviewed_yes.Checked = false;

    if (objInformation.IsReviewed == true)
        rdoIsReviewed_yes.Checked = true;
    else if (objInformation.IsReviewed == false)
        rdoIsReviewed_no.Checked = true;
    else
        rdoIsReviewed_null.Checked = true;

    if (rdoIsReviewed_null.Checked || objInformation.ReviewedDate == null)
        lblReview_Info.Text = "";
    else
        lblReview_Info.Text = "Tổng biên tập: <b>" + objInformation.ReviewedUser + "</b> - Ngày giờ: <b>" + objInformation.ReviewedDate + "</b>";

    #endregion

    ReCheckPermission(false);
}

